'use client';
import { useEffect, useState } from 'react';
import Link from 'next/link';
import toast from 'react-hot-toast';
import CreateButton from '@/components/CreateButton';

export default function AdminCoachesPage() {
  const [coaches, setCoaches] = useState([]);

  const fetchCoaches = async () => {
    try {
      const res = await fetch('http://localhost:5001/api/coaches');
      const data = await res.json();
      setCoaches(Array.isArray(data) ? data : []);
    } catch (err) {
      console.error("Fetch error:", err);
    }
  };

  useEffect(() => { fetchCoaches(); }, []);

  const handleDelete = async (id: string) => {
    if (!confirm('Are you sure you want to remove this coach?')) return;
    try {
      const res = await fetch(`http://localhost:5001/api/coaches/${id}`, {
        method: 'DELETE',
        credentials: 'include', // <--- REQUIRED FOR AUTH
      });
      if (res.ok) {
        toast.success('Coach deleted');
        setCoaches(coaches.filter((c: any) => c.id !== id));
      } else {
        toast.error('Unauthorized: You must be an admin');
      }
    } catch (error) {
      toast.error('Delete failed');
    }
  };

  return (
    <div className="min-h-screen bg-[#020617] text-white p-8">
      <div className="max-w-4xl mx-auto space-y-10">
        <header className="flex flex-col md:flex-row justify-between items-center gap-6">
          <div>
            <h1 className="text-4xl font-black uppercase tracking-tighter">Staff <span className="text-red-600">Management</span></h1>
            <p className="text-slate-500 text-xs font-mono mt-1 uppercase tracking-widest italic">Technical Department DB</p>
          </div>
          <Link href="/admin/coaches/new">
            <CreateButton>Add New Staff</CreateButton>
          </Link>
        </header>

        <div className="grid grid-cols-1 gap-4">
          {coaches.map((coach: any) => (
            <div key={coach.id} className="bg-slate-900 border border-slate-800 p-6 rounded-[1.5rem] flex items-center justify-between group hover:border-red-600/50 transition-all">
              <div className="flex items-center gap-5">
                <img src={coach.image_url} className="w-16 h-16 rounded-full object-cover border-2 border-slate-800 group-hover:border-red-600 transition-colors" />
                <div>
                  <h3 className="font-bold text-lg uppercase tracking-tight">{coach.name}</h3>
                  <div className="flex gap-2 mt-1">
                    <span className="text-[9px] bg-red-600/10 text-red-500 px-2 py-0.5 rounded font-black uppercase">{coach.team_slug.replace('-', ' ')}</span>
                    <span className="text-[9px] bg-slate-800 text-slate-400 px-2 py-0.5 rounded font-black uppercase">{coach.role.replace('_', ' ')}</span>
                  </div>
                </div>
              </div>
              <div className="flex gap-3">
                <Link href={`/admin/coaches/${coach.id}`} className="p-3 bg-slate-800 hover:bg-slate-700 rounded-xl transition-colors">
                  <span className="text-[10px] font-black uppercase tracking-widest">Edit</span>
                </Link>
                <button onClick={() => handleDelete(coach.id)} className="p-3 bg-red-900/10 hover:bg-red-900/30 text-red-500 rounded-xl transition-colors">
                  <span className="text-[10px] font-black uppercase tracking-widest">Delete</span>
                </button>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}